#!/usr/bin/env node
/**
 * Build a single-file JS bundle of this Edge Function for Storage-backed deploy.
 *
 * Why: Supabase MCP deploy_edge_function truncates large payloads; Management API
 * PAT may be unavailable. Production can run a tiny loader that evals this bundle
 * (npm imports injected via globalThis.__kcwReport from the loader).
 *
 * Usage (from repo root, with env set):
 *   node supabase/functions/generate-bank-statement-report/build-storage-bundle.mjs
 *   node supabase/functions/generate-bank-statement-report/build-storage-bundle.mjs --upload
 *
 * Prefer `supabase functions deploy generate-bank-statement-report` when CLI auth works.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname);
const outDir = join(root, ".bundle");
const outFile = join(outDir, "generate-bank-statement-report.bundle.js");
const STORAGE_PATH = "reports/_bundles/generate-bank-statement-report-v18.js";

function stripEnv(name) {
  let v = process.env[name] || "";
  if (v.startsWith(name + "=")) v = v.slice(name.length + 1);
  return v;
}

function minifyLike(src) {
  // Light strip of block comments only — esbuild handles real minify when available.
  return src.replace(/\/\*[\s\S]*?\*\//g, "");
}

async function buildWithEsbuild() {
  const require = createRequire(join(process.cwd(), "package.json"));
  let esbuild;
  try {
    esbuild = require("esbuild");
  } catch {
    return null;
  }
  const result = await esbuild.build({
    entryPoints: [join(root, "index.ts")],
    bundle: true,
    write: false,
    format: "esm",
    platform: "neutral",
    target: "esnext",
    external: ["npm:@supabase/supabase-js@2", "npm:exceljs@4.4.0"],
    banner: {
      js: "// Generated by build-storage-bundle.mjs — do not edit",
    },
  });
  return result.outputFiles[0].text;
}

function injectGlobals(esmSource) {
  let src = esmSource;
  // Rewrite static npm imports to globals injected by the Edge loader.
  src = src.replace(
    /import\s*\{\s*createClient\s*(?:as\s+(\w+))?\s*\}\s*from\s*["']npm:@supabase\/supabase-js@2["']\s*;?/,
    (_m, alias) => {
      const name = alias || "createClient";
      return `const ${name} = globalThis.__kcwReport.createClient;`;
    },
  );
  src = src.replace(
    /import\s+(\w+)\s+from\s*["']npm:exceljs@4\.4\.0["']\s*;?/,
    (_m, alias) => `const ${alias} = globalThis.__kcwReport.ExcelJS;`,
  );
  if (/from\s*["']npm:/.test(src) || /import\s+.*npm:/.test(src)) {
    throw new Error("Bundle still contains npm: imports after rewrite — update build-storage-bundle.mjs");
  }
  return src;
}

async function upload(bundleBytes) {
  const url = stripEnv("NEXT_PUBLIC_SUPABASE_URL").replace(/\/$/, "");
  const key = stripEnv("SUPABASE_SERVICE_KEY") || stripEnv("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("Need NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_KEY");
  const res = await fetch(`${url}/storage/v1/object/bank-statements/${STORAGE_PATH}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      apikey: key,
      "Content-Type": "application/octet-stream",
      "x-upsert": "true",
    },
    body: bundleBytes,
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`Upload failed ${res.status}: ${text}`);
  console.log("Uploaded", STORAGE_PATH, text);
}

const uploadFlag = process.argv.includes("--upload");
mkdirSync(outDir, { recursive: true });

let bundled = await buildWithEsbuild();
if (!bundled) {
  console.warn("esbuild not installed; refusing to emit an incomplete hand-roll. npm i -D esbuild");
  process.exit(1);
}
const finalSrc = injectGlobals(minifyLike(bundled));
writeFileSync(outFile, finalSrc);
console.log("Wrote", outFile, `(${finalSrc.length} bytes)`);

if (uploadFlag) {
  await upload(Buffer.from(finalSrc, "utf8"));
}
